/* Exec Recall – client app. Reads window.SITE_DATA (generated by build.js). */
(function () {
  "use strict";

  const SITE = window.SITE_DATA || { techs: [] };
  const $ = (s, el = document) => el.querySelector(s);
  const main = $("#main"), sidebar = $("#sidebar"), toc = $("#toc");

  /* ---------- small helpers ---------- */
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const slug = (s) => s.toLowerCase().replace(/<[^>]+>/g, "").replace(/[^\w\s-]/g, "").trim().replace(/\s+/g, "-") || "section";
  const store = {
    get(k, d) { try { const v = localStorage.getItem(k); return v === null ? d : JSON.parse(v); } catch (e) { return d; } },
    set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} },
  };
  const done = new Set(store.get("tn-done", []));
  const saveDone = () => store.set("tn-done", [...done]);
  const key = (tech, topic) => `${tech.id}/${topic.id}`;
  const techById = (id) => SITE.techs.find((t) => t.id === id);
  const doneCount = (tech) => tech.topics.filter((t) => done.has(key(tech, t))).length;
  const plain = (md) => md.replace(/```[\s\S]*?```/g, (m) => m.replace(/```\w*/g, " "))
    .replace(/^>\s?/gm, "").replace(/[#*_`|\[\]()\\-]+/g, " ").replace(/\s+/g, " ");

  if (SITE.title) { $("#brandName").textContent = SITE.title; document.title = SITE.title; }

  if (window.marked) marked.setOptions({ gfm: true, breaks: false });

  /* ---------- theme ---------- */
  const hl = $("#hljs-theme");
  function applyTheme(dark) {
    document.documentElement.dataset.theme = dark ? "dark" : "light";
    hl.href = `assets/vendor/hljs-${dark ? "dark" : "light"}.css`;
  }
  applyTheme(document.documentElement.dataset.theme === "dark");
  $("#themeBtn").onclick = () => {
    const dark = document.documentElement.dataset.theme !== "dark";
    applyTheme(dark); store.set("tn-theme", dark ? "dark" : "light");
    if (window.mermaid) location.reload();
  };

  /* ---------- top tabs ---------- */
  function renderTabs(activeId) {
    $("#techTabs").innerHTML = SITE.techs.map((t) =>
      `<a class="tech-tab ${t.id === activeId ? "active" : ""}" href="#/${t.id}">${esc(t.title)}</a>`).join("");
  }

  /* ---------- sidebar ---------- */
  function renderSidebar(tech, activeTopic) {
    if (!tech) { sidebar.innerHTML = ""; return; }
    const pct = tech.topics.length ? Math.round((doneCount(tech) / tech.topics.length) * 100) : 0;
    sidebar.innerHTML = `
      <a class="side-head" href="#/${tech.id}" style="--tech:${tech.color};color:inherit;text-decoration:none">
        <span class="tech-icon">${esc(tech.icon)}</span>
        <span><h3>${esc(tech.title)}</h3><small>${doneCount(tech)}/${tech.topics.length} revised · ${pct}%</small></span>
      </a>
      <div class="progress"><i style="width:${pct}%"></i></div>
      <input class="side-filter" placeholder="Filter topics…" id="sideFilter">
      <ul class="side-list">${tech.topics.map((t) => `
        <li data-title="${esc(t.title.toLowerCase())}"><a href="#/${tech.id}/${t.id}" class="${activeTopic && t.id === activeTopic.id ? "active" : ""}">
          <span>${esc(t.title)}</span>${done.has(key(tech, t)) ? '<span class="done-dot">✓</span>' : ""}
        </a></li>`).join("")}
      </ul>`;
    $("#sideFilter").oninput = (e) => {
      const q = e.target.value.toLowerCase();
      sidebar.querySelectorAll(".side-list li").forEach((li) => (li.style.display = li.dataset.title.includes(q) ? "" : "none"));
    };
    const act = sidebar.querySelector("a.active");
    if (act) act.scrollIntoView({ block: "nearest" });
  }

  /* ---------- views ---------- */
  function viewHome() {
    renderTabs(null); renderSidebar(null); toc.innerHTML = "";
    const totalTopics = SITE.techs.reduce((n, t) => n + t.topics.length, 0);
    const totalDone = SITE.techs.reduce((n, t) => n + doneCount(t), 0);
    const recent = SITE.techs.flatMap((tech) => tech.topics.map((t) => ({ tech, t })))
      .sort((a, b) => (b.t.updated || "").localeCompare(a.t.updated || "")).slice(0, 10);

    main.innerHTML = `
      <section class="hero">
        <h1>${esc(SITE.heading || "Exec")} <span>${esc(SITE.headingAccent || "Recall")}</span></h1>
        <p>${esc(SITE.tagline || "Revision notes, code samples, cheat sheets and interview questions, organised by technology.")}</p>
        <div class="stats">
          <div><b>${SITE.techs.length}</b>technologies</div>
          <div><b>${totalTopics}</b>topics</div>
          <div><b>${totalDone}</b>revised</div>
        </div>
      </section>
      <section class="cards">
        ${SITE.techs.map((t) => {
          const pct = t.topics.length ? Math.round((doneCount(t) / t.topics.length) * 100) : 0;
          return `<a class="card" href="#/${t.id}" style="--tech:${t.color}">
            <div class="card-top"><span class="tech-icon">${esc(t.icon)}</span><h2>${esc(t.title)}</h2></div>
            <p>${esc(t.description || "")}</p>
            <div class="progress"><i style="width:${pct}%"></i></div>
            <div class="card-meta"><span>${t.topics.length} topics</span><span>${pct}% revised</span></div>
          </a>`;
        }).join("")}
        <div class="card add"><div><b>Add a technology</b><br>Create <code>content/&lt;name&gt;/</code>, drop in .md files,<br>then run <code>node build.js</code></div></div>
      </section>
      ${recent.length ? `<section class="recent"><h3>Recently updated</h3><div class="chips">
        ${recent.map(({ tech, t }) => `<a class="chip" href="#/${tech.id}/${t.id}">${esc(tech.title)} · ${esc(t.title)}</a>`).join("")}
      </div></section>` : ""}`;
    document.title = SITE.title || "Exec Recall";
  }

  function viewTech(tech) {
    renderTabs(tech.id); renderSidebar(tech, null); toc.innerHTML = "";
    main.innerHTML = `
      <div class="crumbs"><a href="#/">Home</a><span>/</span><span>${esc(tech.title)}</span></div>
      <div class="overview-head" style="--tech:${tech.color}"><span class="tech-icon">${esc(tech.icon)}</span><h1>${esc(tech.title)}</h1></div>
      <p class="overview-desc">${esc(tech.description || "")}</p>
      ${tech.topics.length ? `<div class="topic-grid">${tech.topics.map((t, i) => `
        <a class="topic-card" href="#/${tech.id}/${t.id}">
          <span class="num">${String(i + 1).padStart(2, "0")}</span>
          <span><div class="t">${esc(t.title)}</div><div class="s">${Math.max(1, Math.round(t.md.split(/\s+/).length / 200))} min read</div></span>
          ${done.has(key(tech, t)) ? '<span class="ok">✓</span>' : ""}
        </a>`).join("")}</div>`
        : `<div class="empty-state"><p>No topics yet. Add Markdown files to <code>content/${esc(tech.id)}/</code> and run:</p><pre>node build.js</pre></div>`}`;
    document.title = `${tech.title} · ${SITE.title || "Exec Recall"}`;
  }

  function viewTopic(tech, topic, heading) {
    renderTabs(tech.id); renderSidebar(tech, topic);
    const i = tech.topics.indexOf(topic);
    const prev = tech.topics[i - 1], next = tech.topics[i + 1];
    const isDone = done.has(key(tech, topic));
    const html = window.marked ? marked.parse(topic.md) : `<pre>${esc(topic.md)}</pre>`;
    const words = topic.md.split(/\s+/).length;

    main.innerHTML = `
      <div class="article">
        <div class="crumbs"><a href="#/">Home</a><span>/</span><a href="#/${tech.id}">${esc(tech.title)}</a><span>/</span><span>${esc(topic.title)}</span></div>
        <article class="md" id="md">${html}</article>
        <nav class="pager">
          ${prev ? `<a class="prev" href="#/${tech.id}/${prev.id}"><small>← Previous</small>${esc(prev.title)}</a>` : ""}
          ${next ? `<a class="next" href="#/${tech.id}/${next.id}"><small>Next →</small>${esc(next.title)}</a>` : ""}
        </nav>
      </div>`;

    const md = $("#md");
    // tools under the H1 (or at top if no H1)
    const tools = document.createElement("div");
    tools.className = "article-tools";
    tools.innerHTML = `<button class="btn ${isDone ? "done" : ""}" id="doneBtn">${isDone ? "✓ Revised" : "Mark as revised"}</button>
      <span>${Math.max(1, Math.round(words / 200))} min read</span>${topic.updated ? `<span>· Updated ${topic.updated}</span>` : ""}`;
    const h1 = md.querySelector("h1");
    h1 ? h1.after(tools) : md.prepend(tools);
    $("#doneBtn").onclick = () => {
      const k = key(tech, topic);
      done.has(k) ? done.delete(k) : done.add(k);
      saveDone(); viewTopic(tech, topic);
    };

    enhanceMarkdown(md, tech, topic);
    buildToc(md, tech, topic);
    document.title = `${topic.title} · ${tech.title}`;

    if (heading) { const el = document.getElementById(heading); if (el) return el.scrollIntoView(); }
    window.scrollTo(0, 0);
  }

  function viewNotFound() {
    renderTabs(null); renderSidebar(null); toc.innerHTML = "";
    main.innerHTML = SITE.techs.length
      ? `<div class="empty-state"><h2>Page not found</h2><p><a href="#/">Go home</a></p></div>`
      : `<div class="empty-state"><h2>No notes yet</h2><p>Put Markdown files in <code>content/&lt;technology&gt;/</code> and build:</p><pre>node build.js</pre></div>`;
  }

  /* ---------- markdown enhancements ---------- */
  function enhanceMarkdown(md, tech, topic) {
    // heading ids + anchors
    const used = {};
    md.querySelectorAll("h1, h2, h3, h4").forEach((h) => {
      let id = slug(h.textContent);
      used[id] = (used[id] || 0) + 1;
      if (used[id] > 1) id += "-" + used[id];
      h.id = id;
      if (h.tagName !== "H1") {
        const a = document.createElement("a");
        a.className = "anchor"; a.textContent = "#"; a.href = `#/${tech.id}/${topic.id}?h=${id}`;
        h.prepend(a);
      }
    });

    // code blocks: highlight, header with language + copy
    md.querySelectorAll("pre > code").forEach((code) => {
      const pre = code.parentElement;
      const lang = ((code.className.match(/language-([\w#+-]+)/) || [])[1] || "").toLowerCase();
      if (lang === "mermaid") {
        const div = document.createElement("div");
        div.className = "mermaid"; div.textContent = code.textContent;
        pre.replaceWith(div); return;
      }
      if (window.hljs) {
        if (lang && hljs.getLanguage(lang)) hljs.highlightElement(code);
        else if (!lang) { code.classList.add("nohighlight"); }
        else hljs.highlightElement(code);
      }
      const wrap = document.createElement("div");
      wrap.className = "code-wrap";
      wrap.innerHTML = `<div class="code-head"><span>${esc(lang || "text")}</span><button class="copy-btn">Copy</button></div>`;
      pre.replaceWith(wrap); wrap.appendChild(pre);
      wrap.querySelector(".copy-btn").onclick = async (e) => {
        try { await navigator.clipboard.writeText(code.textContent); e.target.textContent = "Copied ✓"; }
        catch (err) { e.target.textContent = "Press Ctrl+C"; const r = document.createRange(); r.selectNodeContents(code); getSelection().removeAllRanges(); getSelection().addRange(r); }
        setTimeout(() => (e.target.textContent = "Copy"), 1500);
      };
    });

    // interactive checklists remembered per topic
    const boxes = md.querySelectorAll('input[type="checkbox"]');
    const ck = "tn-check-" + key(tech, topic);
    const saved = store.get(ck, {});
    boxes.forEach((b, i) => {
      b.disabled = false;
      if (i in saved) b.checked = saved[i];
      b.onchange = () => { saved[i] = b.checked; store.set(ck, saved); };
    });

    // external links open in new tab
    md.querySelectorAll('a[href^="http"]').forEach((a) => { a.target = "_blank"; a.rel = "noopener"; });

    // in-page links like (#some-heading) → route-aware
    md.querySelectorAll('a[href^="#"]:not(.anchor)').forEach((a) => {
      const h = a.getAttribute("href").slice(1);
      if (h && !h.startsWith("/")) a.href = `#/${tech.id}/${topic.id}?h=${h}`;
    });

    // tables: wrap kept by CSS; mermaid lazy load
    if (md.querySelector(".mermaid")) loadMermaid();
  }

  function loadMermaid() {
    const run = () => { mermaid.initialize({ startOnLoad: false, theme: document.documentElement.dataset.theme === "dark" ? "dark" : "default" }); mermaid.run({ querySelector: ".mermaid" }); };
    if (window.mermaid) return run();
    const s = document.createElement("script");
    s.src = "assets/vendor/mermaid.min.js";
    s.onload = run; document.head.appendChild(s);
  }

  /* ---------- table of contents + scroll spy ---------- */
  let spy;
  function buildToc(md, tech, topic) {
    const hs = [...md.querySelectorAll("h2, h3")];
    if (hs.length < 2) { toc.innerHTML = ""; return; }
    toc.innerHTML = `<h4>On this page</h4><ul>${hs.map((h) =>
      `<li><a class="lvl${h.tagName[1]}" data-id="${h.id}" href="#/${tech.id}/${topic.id}?h=${h.id}">${esc(h.textContent.replace(/^#/, ""))}</a></li>`).join("")}</ul>`;
    if (spy) spy.disconnect();
    const links = new Map([...toc.querySelectorAll("a")].map((a) => [a.dataset.id, a]));
    spy = new IntersectionObserver((entries) => {
      entries.forEach((en) => {
        if (en.isIntersecting) {
          links.forEach((a) => a.classList.remove("active"));
          const a = links.get(en.target.id); if (a) a.classList.add("active");
        }
      });
    }, { rootMargin: "-70px 0px -70% 0px" });
    hs.forEach((h) => spy.observe(h));
  }

  /* ---------- router ---------- */
  function route() {
    document.body.classList.remove("nav-open");
    const raw = location.hash.replace(/^#\/?/, "");
    const [p, q] = raw.split("?");
    const heading = new URLSearchParams(q || "").get("h");
    const [techId, topicId] = p.split("/").filter(Boolean).map(decodeURIComponent);
    if (!techId) return SITE.techs.length ? viewHome() : viewNotFound();
    const tech = techById(techId);
    if (!tech) return viewNotFound();
    if (!topicId) return viewTech(tech);
    const topic = tech.topics.find((t) => t.id === topicId);
    if (!topic) return viewNotFound();
    store.set("tn-last", raw);
    viewTopic(tech, topic, heading);
  }

  // Same-page heading clicks: just scroll, don't re-render
  document.addEventListener("click", (e) => {
    const a = e.target.closest('a[href*="?h="]');
    if (!a) return;
    const [path, q] = a.getAttribute("href").replace(/^#\/?/, "").split("?");
    const cur = location.hash.replace(/^#\/?/, "").split("?")[0];
    if (path === cur) {
      e.preventDefault();
      const el = document.getElementById(new URLSearchParams(q).get("h"));
      if (el) { el.scrollIntoView({ behavior: "smooth" }); history.replaceState(null, "", a.getAttribute("href")); }
    }
  });

  window.addEventListener("hashchange", route);

  /* ---------- search ---------- */
  const modal = $("#searchModal"), input = $("#searchInput"), results = $("#searchResults");
  let index = null, sel = 0;
  function buildIndex() {
    index = SITE.techs.flatMap((tech) => tech.topics.map((t) => {
      const sections = [];
      let cur = { heading: null, text: "" };
      for (const line of t.md.split("\n")) {
        const m = line.match(/^(#{2,3})\s+(.*)/);
        if (m) { sections.push(cur); cur = { heading: m[2].replace(/[*`\\]/g, ""), text: "" }; }
        else cur.text += line + "\n";
      }
      sections.push(cur);
      return { tech, t, titleL: t.title.toLowerCase(), sections: sections.map((s) => ({ ...s, plain: plain(s.text), headL: (s.heading || "").toLowerCase() })) };
    }));
  }
  const hi = (text, q) => {
    const i = text.toLowerCase().indexOf(q);
    if (i < 0) return esc(text);
    return esc(text.slice(0, i)) + "<mark>" + esc(text.slice(i, i + q.length)) + "</mark>" + esc(text.slice(i + q.length));
  };
  function doSearch() {
    if (!index) buildIndex();
    const q = input.value.trim().toLowerCase();
    if (!q) { results.innerHTML = `<div class="search-empty">Type to search ${index.length} topics across ${SITE.techs.length} technologies</div>`; return; }
    const out = [];
    for (const d of index) {
      const href = `#/${d.tech.id}/${d.t.id}`;
      if (d.titleL.includes(q)) out.push({ score: 3, href, title: hi(d.t.title, q), tech: d.tech.title, snip: "Topic" });
      for (const s of d.sections) {
        if (s.heading && s.headL.includes(q)) out.push({ score: 2, href: href + "?h=" + slug(s.heading), title: hi(s.heading, q), tech: `${d.tech.title} · ${d.t.title}`, snip: s.plain.slice(0, 120) });
        else {
          const i = s.plain.toLowerCase().indexOf(q);
          if (i >= 0) {
            const start = Math.max(0, i - 40);
            out.push({ score: 1, href: href + (s.heading ? "?h=" + slug(s.heading) : ""), title: esc(s.heading || d.t.title), tech: `${d.tech.title} · ${d.t.title}`,
              snip: (start ? "…" : "") + hi(s.plain.slice(start, i + q.length + 80), q) + "…", raw: true });
          }
        }
      }
    }
    out.sort((a, b) => b.score - a.score);
    const top = out.slice(0, 40);
    sel = 0;
    results.innerHTML = top.length ? top.map((r, i) => `
      <a class="result ${i === 0 ? "sel" : ""}" href="${r.href}">
        <div class="rt">${r.title}<small>${esc(r.tech)}</small></div>
        <div class="rs">${r.raw ? r.snip : esc(r.snip)}</div>
      </a>`).join("") : `<div class="search-empty">No results for “${esc(q)}”</div>`;
  }
  function openSearch() { modal.hidden = false; input.value = ""; doSearch(); input.focus(); }
  function closeSearch() { modal.hidden = true; }
  $("#searchBtn").onclick = openSearch;
  input.oninput = doSearch;
  modal.onclick = (e) => { if (e.target === modal || e.target.closest(".result")) closeSearch(); };
  input.onkeydown = (e) => {
    const items = [...results.querySelectorAll(".result")];
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      if (!items.length) return;
      items[sel].classList.remove("sel");
      sel = (sel + (e.key === "ArrowDown" ? 1 : -1) + items.length) % items.length;
      items[sel].classList.add("sel"); items[sel].scrollIntoView({ block: "nearest" });
    } else if (e.key === "Enter" && items[sel]) { location.hash = items[sel].getAttribute("href"); closeSearch(); }
  };
  document.addEventListener("keydown", (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k") { e.preventDefault(); modal.hidden ? openSearch() : closeSearch(); }
    else if (e.key === "/" && modal.hidden && !/input|textarea/i.test(document.activeElement.tagName)) { e.preventDefault(); openSearch(); }
    else if (e.key === "Escape") { closeSearch(); document.body.classList.remove("nav-open"); }
  });

  /* ---------- mobile menu, back to top ---------- */
  $("#menuBtn").onclick = () => {
    if (!sidebar.innerHTML) { // on home: show tech list in drawer
      sidebar.innerHTML = `<ul class="side-list">${SITE.techs.map((t) => `<li data-title=""><a href="#/${t.id}">${esc(t.title)}</a></li>`).join("")}</ul>`;
    }
    document.body.classList.toggle("nav-open");
  };
  $("#scrim").onclick = () => document.body.classList.remove("nav-open");
  const toTop = $("#toTop");
  window.addEventListener("scroll", () => toTop.classList.toggle("show", scrollY > 600), { passive: true });
  toTop.onclick = () => scrollTo({ top: 0, behavior: "smooth" });

  route();
})();
